package companion

const planStyle = `<style>
.key-toast{position:fixed;top:max(16px,env(safe-area-inset-top));left:50%;right:auto;bottom:auto;z-index:2147483647;transform:translateX(-50%);margin:0;display:flex;align-items:flex-start;gap:10px;width:max-content;max-width:min(440px,calc(100vw - 32px));padding:10px 10px 10px 14px;border:1px solid var(--border-strong);border-radius:10px;background:#fff;box-shadow:0 14px 36px rgba(30,27,24,.18),0 2px 8px rgba(30,27,24,.08);color:var(--text)}.key-toast:not(:popover-open){display:none}.key-toast::backdrop{background:transparent}.key-toast-icon{display:grid;place-items:center;flex:none;width:28px;height:28px;margin-top:2px;border-radius:50%;background:rgba(15,143,101,.1);color:var(--success);font-size:16px;font-weight:750}.key-toast-message{min-width:0;flex:1;padding:4px 0;font-size:13px;font-weight:500;line-height:1.5;overflow-wrap:anywhere}.key-toast button{display:grid;place-items:center;flex:none;width:30px;height:30px;padding:0;border:0;border-radius:7px;background:transparent;color:var(--muted);font-size:18px;line-height:1}.key-toast button:hover{background:var(--surface-hover);color:var(--text)}.key-actions{display:flex;flex-wrap:wrap;align-items:center;gap:6px}.key-actions form{margin:0}.plan-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:12px}.plan-card{padding:16px;border:1px solid var(--border-strong);border-radius:10px;background:var(--bg)}.plan-card h3{margin:0 0 10px;font-size:14px}.plan-meta{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0;color:var(--muted);font-size:12px}.plan-account{display:grid;grid-template-columns:auto minmax(0,1fr) 90px;align-items:center;gap:8px;padding:9px 0;border-top:1px solid var(--border);font-size:12px}.plan-account input[type=number]{width:90px}.plan-form{display:grid;gap:12px}.plan-time{display:grid;grid-template-columns:1fr 1fr;gap:10px}.plan-time label{display:grid;gap:5px;font-size:12px}.quota-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:12px}.quota-card{padding:18px;border:1px solid var(--border);border-radius:10px;background:var(--bg)}.quota-card h3{margin:0;font-size:14px}.quota-meter{height:7px;overflow:hidden;border-radius:9px;background:var(--border-strong)}.quota-meter span{display:block;height:100%;border-radius:9px;background:var(--success)}.quota-meter.low span{background:var(--danger)}.quota-row{display:grid;gap:6px;margin:14px 0}.quota-row-head{display:flex;align-items:baseline;justify-content:space-between;gap:8px;font-size:12px}.quota-name{font-size:13px}.quota-row-values{display:flex;align-items:baseline;justify-content:flex-end;gap:7px;flex-wrap:wrap;text-align:right}.quota-percent{font-size:14px}.quota-reset-at,.quota-reset-relative{color:var(--muted);font-variant-numeric:tabular-nums}.quota-reset-relative.urgent{color:var(--danger);font-weight:700}.reset-expiry{margin:16px 0 18px}.reset-expiry-title{margin-bottom:9px;color:var(--muted);font-size:12px;font-weight:700}.reset-expiry-item{display:flex;justify-content:space-between;gap:8px;margin-top:6px;padding:9px 11px;border:1px solid var(--border);border-radius:7px;background:var(--surface);color:var(--muted);font-size:12px;font-variant-numeric:tabular-nums}.reset-expiry-item span:last-child{text-align:right}.quota-row small{color:var(--muted)}.plan-note{padding:11px 13px;border-radius:8px;background:#fff8e6;color:#755c20;font-size:12px}.minor{font-size:11px;color:var(--muted)}.reset-confirm-dialog{width:min(420px,calc(100vw - 32px));padding:0;border:1px solid var(--border-strong);border-radius:12px;background:var(--bg);color:var(--text);box-shadow:0 22px 60px rgba(30,27,24,.25)}.reset-confirm-dialog::backdrop{background:rgba(28,26,24,.5)}.reset-confirm-content{padding:24px 24px 19px}.reset-confirm-content h2{margin:0 0 9px;font-size:18px;font-weight:720;letter-spacing:-.02em}.reset-confirm-content p{margin:0;color:var(--muted);font-size:12.5px;line-height:1.65}.reset-confirm-account{display:block;margin:12px 0;padding:10px 12px;border:1px solid var(--border);border-radius:8px;background:var(--surface);font-size:13px;font-weight:700;overflow-wrap:anywhere}.reset-confirm-actions{display:flex;justify-content:flex-end;gap:8px;padding:14px 24px;border-top:1px solid var(--border)}
.endpoint-groups{display:grid;gap:14px;margin-top:18px;padding-top:15px;border-top:1px solid var(--border)}.endpoint-group-title{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:0 0 8px;color:var(--muted);font-size:11px;font-weight:700}.endpoint-group-title small{color:var(--quiet);font-size:10px;font-weight:500}.endpoint-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}.endpoint-item{display:flex;align-items:flex-start;gap:7px;min-width:0;padding:5px 7px;border:1px solid var(--border);border-radius:6px;background:var(--bg)}.endpoint-method{flex:none;color:var(--success);font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:10px;font-weight:750}.endpoint-item code{min-width:0;color:var(--text);font-size:10.5px;line-height:1.35;overflow-wrap:anywhere}
@media(max-width:600px){.quota-grid{grid-template-columns:1fr}.reset-expiry-item{flex-wrap:wrap}.plan-time{grid-template-columns:1fr}.plan-account{grid-template-columns:auto minmax(0,1fr)}.plan-account input[type=number]{grid-column:2;width:100%}.endpoint-list{grid-template-columns:1fr}}
</style>`

const dashboardPlanTemplate = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>我的密钥 · CPA Companion</title>` + pageStyle + planStyle + dashboardTimelineStyle + `</head><body><div class="shell"><aside class="sidebar"><a class="brand" href="/keys"><img class="brand-mark" src="/assets/logo.png" width="30" height="30" alt=""><span class="brand-copy"><span class="brand-title">CPA Companion</span>` + brandVersionTemplate + `</span></a><nav class="nav"><span class="nav-label">工作台</span><a class="nav-link" href="/dashboard">仪表盘</a><a class="nav-link active" href="/keys">我的密钥</a>{{if .Admin}}<a class="nav-link" href="/admin">分流方案</a><a class="nav-link" href="/audit">内容审计</a>{{end}}<a class="nav-link" href="/prices">模型价格</a><a class="nav-link" href="/logs">使用日志</a></nav>` + sidebarGitHubTemplate + `<div class="sidebar-footer"><div class="identity"><span class="avatar"><span class="avatar-fallback">C</span>{{if .User.AvatarURL}}<img src="{{.User.AvatarURL}}" alt="" referrerpolicy="no-referrer">{{end}}</span><span class="identity-copy"><span class="identity-name">{{.User.Username}}</span><span class="identity-meta">{{.User.ID}}</span></span></div><form method="post" action="/auth/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="logout">退出登录</button></form></div></aside><main class="content"><div class="content-inner"><header class="page-head"><div><h1>我的 API Key</h1><p>查看分流方案、上游额度，管理你的密钥。</p></div></header>

<div class="summary-grid"><section class="surface surface-pad"><div class="surface-head"><div><h2 class="surface-title">当前分流方案</h2><p class="surface-description">方案有效期间，密钥可以调用模型。</p></div>{{if .PlanActive}}<span class="status">生效中</span>{{else}}<span class="status waiting">不可用</span>{{end}}</div>{{if .HasPlan}}<div class="value">{{.Plan.Name}}</div><div class="plan-meta">账号时段合集（北京时间）：{{range .Plan.Periods}}<span>{{.}}</span>{{end}}</div><div class="plan-meta">每分钟请求数：{{if .Plan.RPM}}{{.Plan.RPM}} RPM{{else}}不限制{{end}}</div>{{if .Plan.BudgetPicoUSD}}<div class="quota-row"><div class="quota-row-head"><span>方案使用额度（USD）</span><strong>${{.Plan.UsedUSD}} / ${{.Plan.BudgetUSD}}</strong></div><div class="quota-meter" role="meter" aria-valuemin="0" aria-valuemax="100" aria-valuenow="{{.Plan.BudgetPercent}}"><span style="width:{{.Plan.BudgetPercent}}%"></span></div><small>按模型价格与上游用量结算；搜索无用量时按请求和响应大小估算。达到额度后停止新请求。</small></div>{{end}}{{if .Plan.UsageError}}<p class="plan-note">计费数据缺失，方案已暂停。请联系管理员检查模型用量并重新保存方案。</p>{{else if and .Plan.BudgetPicoUSD (ge .Plan.UsedPicoUSD .Plan.BudgetPicoUSD)}}<p class="plan-note">方案使用额度已用尽，请联系管理员。</p>{{else if not .PlanActive}}<p class="plan-note">当前没有处于可用时段的上游账号，请联系管理员。</p>{{else}}<p class="helper">已分配账号id：{{range .Accounts}}<code>{{.Account.Prefix}}</code> {{else}}账号信息暂不可用{{end}}</p>{{end}}{{else}}<p class="plan-note">尚未分配分流方案，暂不能创建或使用 API Key。</p>{{end}}</section><section class="surface surface-pad"><div class="surface-head"><div><h2 class="surface-title">接口地址</h2><p class="surface-description">填写到 OpenAI 兼容客户端的 Base URL。</p></div></div><div class="inline-field"><code id="base-url">{{.BaseURL}}</code><button type="button" class="button secondary small" data-copy-target="base-url">复制</button></div><div class="endpoint-groups"><div class="endpoint-group"><div class="endpoint-group-title"><span>支持的端点</span><small>域名下的完整路径</small></div><div class="endpoint-list">{{range .Endpoints}}<div class="endpoint-item"><span class="endpoint-method">{{.Method}}</span><code title="{{.Path}}">{{.Path}}</code></div>{{end}}</div></div></div></section></div>
{{if and .HasPlan .Plan.AccountIDs}}<section class="surface surface-pad section-space"><div class="surface-head"><div><h2 class="surface-title">上游额度</h2><p class="surface-description">只展示方案中的账号；额度由 CPA 按账号实时查询。</p></div><span class="status waiting">{{len .Accounts}} 个</span></div><div class="availability" data-availability><div class="availability-toolbar"><strong>账号可用时段 · 北京时间</strong><div class="availability-controls"><button type="button" data-availability-prev aria-label="上一时间段">‹</button><span class="availability-period" data-availability-period></span><button type="button" data-availability-next aria-label="下一时间段">›</button><button type="button" data-availability-today>今天</button><button type="button" data-availability-days="7">7 天</button><button type="button" data-availability-days="14">14 天</button><button type="button" data-availability-full>全时段</button></div></div><div class="availability-board" data-availability-board></div><div class="availability-legend"><span><i></i>账号可用</span><span class="past"><i></i>已过去</span><span class="aggregate"><i></i>方案可用时段（合集）</span><span class="today"><i></i>当前时间</span></div></div><div class="quota-grid">{{range .Accounts}}<article class="quota-card" data-availability-account data-account-name="{{.Account.Provider}} · {{.Account.Prefix}}" data-start="{{.StartInput}}" data-end="{{.EndInput}}"><h3>{{.Account.Provider}} · {{.Account.Prefix}}</h3><div class="minor">账号 ID：{{.Account.Prefix}} · 优先级 {{.Account.PriorityText}} · {{if .Active}}当前可用{{else}}当前时段未开放{{end}}</div><div class="minor">时段：{{if .StartInput}}{{.StartInput}}{{else}}立即{{end}} ～ {{if .EndInput}}{{.EndInput}}{{else}}永久{{end}}（北京时间）</div>{{if gt .ResetLimit 0}}<div class="reset-expiry"><div class="reset-expiry-title">主动重置过期时间（GMT+8）</div>{{range .ResetExpiries}}<div class="reset-expiry-item"><span>第 {{.Order}} 次</span><span>{{.AtText}} · {{.RelativeText}}</span></div>{{else}}<p class="minor">上游暂未提供可用重置额度的逐次过期时间。</p>{{end}}</div>{{end}}{{if .Error}}<p class="helper">{{.Error}}</p>{{else}}{{range .Windows}}<div class="quota-row"><div class="quota-row-head"><strong class="quota-name">{{.Name}}</strong><div class="quota-row-values"><strong class="quota-percent">{{.Remaining}}%</strong>{{if .ResetAt}}<span class="quota-reset-at">{{.ResetAtText}}</span><span class="quota-reset-relative {{if .ResetSoon}}urgent{{end}}">· {{.ResetRelativeText}}</span>{{end}}</div></div><div class="quota-meter {{if .Low}}low{{end}}" role="meter" aria-valuemin="0" aria-valuemax="100" aria-valuenow="{{.Remaining}}"><span style="width:{{.Remaining}}%"></span></div></div>{{end}}{{end}}<div class="plan-meta">重置次数：已用 {{.ResetUsed}} / {{.ResetLimit}} · 上游当前可用 {{.ResetAvailable}}</div>{{if and .Active (lt .ResetUsed .ResetLimit) (gt .ResetAvailable 0)}}<form method="post" action="/quota/reset" data-reset-form><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="account" value="{{.Ref}}"><button class="button secondary small" data-reset-account="{{.Account.Provider}} · {{.Account.Prefix}}">重置此账号额度</button></form>{{end}}</article>{{end}}</div></section>{{end}}
<div class="stack section-space"><section class="surface surface-pad"><div class="surface-head"><div><h2 class="surface-title">创建 API Key</h2><p class="surface-description">按用途命名，创建后可在密钥列表中复制。</p></div></div><form class="form-row" method="post" action="/keys"><input type="hidden" name="csrf" value="{{.CSRF}}"><div class="field"><label for="key-name">密钥名称</label><input id="key-name" class="input" name="name" maxlength="80" required placeholder="例如：本地 Codex" {{if not .PlanActive}}disabled{{end}}></div><button class="button" {{if not .PlanActive}}disabled{{end}}>创建密钥</button></form></section><section class="surface surface-pad"><div class="surface-head"><div><h2 class="surface-title">已有密钥</h2><p class="surface-description">可以复制或轮换密钥；轮换后旧密钥立即失效。</p></div><span class="status waiting">{{len .Keys}} 个</span></div>{{if .Keys}}<div class="table-wrap"><table class="table"><thead><tr><th>名称</th><th>密钥 ID</th><th>创建时间</th><th>操作</th></tr></thead><tbody>{{range .Keys}}<tr><td>{{.Name}}</td><td><code>{{.ID}}</code></td><td>{{.CreatedAt.Format "2006-01-02 15:04"}}</td><td><div class="key-actions"><form method="post" action="/keys/copy" data-key-copy><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><button type="submit" class="button secondary small">复制密钥</button></form><form method="post" action="/keys/rotate" data-confirm="轮换后旧密钥立即失效，需要更新所有使用它的客户端。确定轮换？"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><button class="button secondary small">轮换密钥</button></form><form method="post" action="/keys/revoke"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><button class="button danger small">撤销</button></form></div></td></tr>{{end}}</tbody></table></div>{{else}}<div class="empty">还没有 API Key。</div>{{end}}</section></div></div></main></div>
<div class="key-toast" id="key-toast" popover="manual" data-message="{{.KeyNotice}}" role="status"><span class="key-toast-icon" aria-hidden="true">✓</span><span class="key-toast-message">{{.KeyNotice}}</span><button type="button" id="key-toast-close" aria-label="关闭提示">×</button></div>
<dialog class="reset-confirm-dialog" id="reset-confirm-dialog" aria-labelledby="reset-confirm-title" aria-describedby="reset-confirm-description"><div class="reset-confirm-content"><h2 id="reset-confirm-title">确认重置上游额度</h2><p id="reset-confirm-description">将为以下账号执行一次上游额度重置，并消耗一次已分配的重置次数。</p><strong class="reset-confirm-account" id="reset-confirm-account"></strong><p>请确认账号无误后继续。</p></div><div class="reset-confirm-actions"><button type="button" class="button secondary" data-reset-cancel>取消</button><button type="button" class="button" data-reset-confirm>确认重置</button></div></dialog>` + confirmScript + pageScript + selectControlScript + resetConfirmScript + keyToastScript + dashboardTimelineScript + navigationScript + `</body></html>`

const resetConfirmScript = `<script>
(() => {
  const dialog = document.getElementById('reset-confirm-dialog');
  const account = document.getElementById('reset-confirm-account');
  const confirm = dialog.querySelector('[data-reset-confirm]');
  let pending = null;
  let confirmed = false;
  document.querySelectorAll('[data-reset-form]').forEach(form => {
    form.addEventListener('submit', event => {
      if (confirmed) return;
      event.preventDefault();
      pending = form;
      account.textContent = form.querySelector('[data-reset-account]').dataset.resetAccount;
      dialog.showModal();
    });
  });
  dialog.querySelector('[data-reset-cancel]').addEventListener('click', () => dialog.close());
  dialog.addEventListener('click', event => { if (event.target === dialog) dialog.close(); });
  dialog.addEventListener('close', () => { pending = null; });
  confirm.addEventListener('click', () => {
    if (!pending || confirmed) return;
    const form = pending;
    confirmed = true;
    confirm.disabled = true;
    form.requestSubmit();
    confirmed = false;
  });
})();
</script>`

const keyToastScript = `<script>
(() => {
  const toast = document.getElementById('key-toast');
  if (!toast || !toast.dataset.message) return;
  toast.showPopover();
  const timer = setTimeout(() => toast.hidePopover(), 6500);
  document.getElementById('key-toast-close').addEventListener('click', () => { clearTimeout(timer); toast.hidePopover(); });
})();
</script>`
